1	import { useRef, useState, useEffect, useMemo } from 'react';
2	import { useNavigate, useParams } from 'react-router-dom';
3	import { useFights } from '../hooks/useFights';
4	import { useEvents } from '../hooks/useEvents';
5	import { useFighterFrames } from '../hooks/useFighterFrames';
6	import { useRounds } from '../hooks/useRounds';
7	import { useWindowWidth } from '../hooks/useWindowWidth';
8	import { useAuth } from '../hooks/useAuth';
9	import {
10	  createEvent, updateEvent, deleteEvent, finishLabeling, deleteFight, reopenLabeling, videoUrl,
11	  type CreateEventPayload,
12	} from '../services/api';
13	import type { SpanKind } from '../components/annotate/taxonomy';
14	import { isEditingLabels, isFightViewable, isLabelEditable, isLabelingReady, needsRoundReview, STATE_LABELS } from '../types/Fight';
15	import type { Event } from '../types/Event';
16	import { describeEvent } from '../utils/describeEvent';
17	import { isFrameSwapped } from '../utils/cornerSwap';
18	import ConfirmDialog from '../components/ConfirmDialog';
19	import VideoControls from '../components/VideoControls';
20	import FrameInfo from '../components/FrameInfo';
21	import type { FighterOverlayHandle } from '../components/FighterOverlay';
22	import AnnotateStage from '../components/annotate/AnnotateStage';
23	import FighterSelectCard from '../components/annotate/FighterSelectCard';
24	import EventPalette from '../components/annotate/EventPalette';
25	import FightEndModal, { type FightEndResult } from '../components/annotate/FightEndModal';
26	import KeyboardLegend from '../components/annotate/KeyboardLegend';
27	import AnnotationPanel from '../components/annotate/AnnotationPanel';
28	import SaveStatus from '../components/annotate/SaveStatus';
29	import FightPurposeBadge from '../components/FightPurposeBadge';
30	import { KEYMAP, colorForAction, iconForAction, successForAction, type Corner, type ToolItem } from '../components/annotate/taxonomy';
31	
32	export default function Annotate() {
33	  const { id } = useParams<{ id: string }>();
34	  const navigate = useNavigate();
35	  const fightId = id ? Number(id) : null;
36	  const { can } = useAuth();
37	
38	  const videoRef = useRef<HTMLVideoElement>(null);
39	  const overlayRef = useRef<FighterOverlayHandle>(null);
40	  const rafRef = useRef<number | null>(null);
41	  const fpsRef = useRef<number>(30);
42	  const lastFrameRef = useRef<number>(-1);
43	  const [isPlaying, setIsPlaying] = useState(false);
44	  const [currentTime, setCurrentTime] = useState(0);
45	  const [duration, setDuration] = useState(0);
46	
47	  const { fights, setFights } = useFights();
48	  const selectedFight = fights.find(f => f.id === fightId) ?? null;
49	  const { events: allEvents, setEvents: setAllEvents } = useEvents(fightId, { source: 'label' });
50	  const events = useMemo(() => allEvents.filter(e => e.kind === 'point'), [allEvents]);
51	  const spans = useMemo(() => allEvents.filter(e => e.kind !== 'point'), [allEvents]);
52	  const { frameMap } = useFighterFrames(fightId);
53	  const { rounds } = useRounds(fightId);
54	  const width = useWindowWidth();
55	  const narrow = width < 1100;
56	
57	  const fps = selectedFight?.fps ?? 30;
58	  fpsRef.current = fps;
59	
60	  const ready = selectedFight !== null && isLabelingReady(selectedFight.state);
61	
62	  useEffect(() => {
63	    const video = videoRef.current;
64	    if (!video || !ready) return;
65	    if (!isPlaying) {
66	      if (rafRef.current !== null) {
67	        video.cancelVideoFrameCallback(rafRef.current);
68	        rafRef.current = null;
69	      }
70	      return;
71	    }
72	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
73	      const frame = Math.floor(metadata.mediaTime * fpsRef.current) + 1;
74	      overlayRef.current?.draw(frame);
75	      if (frame !== lastFrameRef.current) {
76	        lastFrameRef.current = frame;
77	        setCurrentTime(metadata.mediaTime);
78	      }
79	      rafRef.current = video.requestVideoFrameCallback(tick);
80	    };
81	    rafRef.current = video.requestVideoFrameCallback(tick);
82	    return () => {
83	      if (rafRef.current !== null) {
84	        video.cancelVideoFrameCallback(rafRef.current);
85	        rafRef.current = null;
86	      }
87	    };
88	  }, [isPlaying, ready]);
89	
90	  const currentFrame = Math.floor(currentTime * fps) + 1;
91	  const currentMs = Math.floor(currentTime * 1000);
92	  const videoSrc = selectedFight ? videoUrl(selectedFight.id) : undefined;
93	
94	  const togglePlay = () => {
95	    const video = videoRef.current;
96	    if (!video) return;
97	    if (isPlaying) video.pause(); else video.play();
98	    setIsPlaying(!isPlaying);
99	  };
100	
101	  const stepFrame = (delta: number) => {
102	    const video = videoRef.current;
103	    if (!video) return;
104	    video.pause();
105	    setIsPlaying(false);
106	    const newTime = Math.min(Math.max(video.currentTime + delta / fps, 0), video.duration);
107	    video.currentTime = newTime;
108	    setCurrentTime(newTime);
109	    overlayRef.current?.draw(Math.floor(newTime * fpsRef.current) + 1);
110	  };
111	
112	  const handleSeek = (time: number) => {
113	    const video = videoRef.current;
114	    if (!video) return;
115	    video.currentTime = time;
116	    setCurrentTime(time);
117	    overlayRef.current?.draw(Math.floor(time * fpsRef.current) + 1);
118	  };
119	
120	  const seekToFrame = (frame: number) => handleSeek(Math.max(0, (frame - 1) / fps));
121	
122	  const currentRound = rounds.find(r => currentFrame >= r.start_frame && currentFrame <= r.end_frame)?.round_number ?? '-';
123	
124	  const redName = selectedFight?.red_fighter_name ?? 'Red corner';
125	  const blueName = selectedFight?.blue_fighter_name ?? 'Blue corner';
126	
127	  // Reconstructs each point event's display text on the fly (description is
128	  // only ever stored for fight_end) — including the swap-corrected fighter
129	  // name for any event whose own frame falls inside a corner_swap span, so
130	  // reviewing the timeline reflects a swap the moment it's marked, even for
131	  // strikes logged before the span existed.
132	  const cornerSwapSpans = useMemo(
133	    () => spans.filter(s => s.kind === 'corner_swap').map(s => ({ frame: s.frame, end_frame: s.end_frame })),
134	    [spans],
135	  );
136	  const describe = (e: Event) => describeEvent(e, {
137	    redName, blueName, swapped: isFrameSwapped(e.frame, cornerSwapSpans),
138	  });
139	
140	  // ---- annotation logging state ----
141	  const [selected, setSelected] = useState<Corner | null>(null);
142	  const [toast, setToast] = useState<{ text: string; color: string; icon: string } | null>(null);
143	  const [flashId, setFlashId] = useState<number | null>(null);
144	  const [hint, setHint] = useState(false);
145	  const [endOpen, setEndOpen] = useState(false);
146	  const [savingCount, setSavingCount] = useState(0);
147	  const [finishing, setFinishing] = useState(false);
148	  const [reopening, setReopening] = useState(false);
149	  const [reopenError, setReopenError] = useState<string | null>(null);
150	  const [confirmDelete, setConfirmDelete] = useState(false);
151	  const [deletingFight, setDeletingFight] = useState(false);
152	  const [deleteError, setDeleteError] = useState<string | null>(null);
153	  // Timeline clip selected by click — Delete removes it. Separate from
154	  // `flashId` (a transient highlight after creation) and from `selected`
155	  // (the red/blue corner for the *next* logged event).
156	  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
157	
158	  const frameRef = useRef(1);
159	  frameRef.current = currentFrame;
160	  const selRef = useRef<Corner | null>(null);
161	  selRef.current = selected;
162	  const endOpenRef = useRef(false);
163	  endOpenRef.current = endOpen;
164	  const confirmDeleteRef = useRef(false);
165	  confirmDeleteRef.current = confirmDelete;
166	  const selectedEventIdRef = useRef<number | null>(null);
167	  selectedEventIdRef.current = selectedEventId;
168	  const sessionIdsRef = useRef<number[]>([]);
169	
170	  const toastTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
171	  const hintTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
172	  const flashTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
173	
174	  const showToast = (text: string, color: string, icon: string) => {
175	    setToast({ text, color, icon });
176	    clearTimeout(toastTimer.current);
177	    toastTimer.current = setTimeout(() => setToast(null), 1100);
178	  };
179	
180	  const flash = (eventId: number) => {
181	    setFlashId(eventId);
182	    clearTimeout(flashTimer.current);
183	    flashTimer.current = setTimeout(() => setFlashId(null), 700);
184	  };
185	
186	  const addEvent = async (payload: CreateEventPayload) => {
187	    if (!fightId) return null;
188	    setSavingCount(c => c + 1);
189	    try {
190	      const created = await createEvent(fightId, { kind: 'point', ...payload });
191	      setAllEvents(prev => [...prev, created]);
192	      sessionIdsRef.current.push(created.id);
193	      flash(created.id);
194	      return created;
195	    } catch {
196	      showToast('Failed to save event', 'var(--f-red)', 'error');
197	      return null;
198	    } finally {
199	      setSavingCount(c => c - 1);
200	    }
201	  };
202	
203	  const removeEvent = async (eventId: number) => {
204	    if (!fightId) return;
205	    setSavingCount(c => c + 1);
206	    try {
207	      await deleteEvent(fightId, eventId);
208	      setAllEvents(prev => prev.filter(e => e.id !== eventId));
209	      sessionIdsRef.current = sessionIdsRef.current.filter(x => x !== eventId);
210	      if (selectedEventIdRef.current === eventId) setSelectedEventId(null);
211	    } catch {
212	      showToast('Failed to delete event', 'var(--f-red)', 'error');
213	    } finally {
214	      setSavingCount(c => c - 1);
215	    }
216	  };
217	
218	  // corner_swap / excluded are start/end toggles: one key opens a span at the
219	  // playhead, the next press of the same key closes it. `openSpanRef` tracks
220	  // the in-flight span id per kind so the second press knows what to close.
221	  const openSpanRef = useRef<Partial<Record<SpanKind, number>>>({});
222	  const SPAN_LABEL: Record<SpanKind, string> = { round: 'Round', corner_swap: 'Corner swap', excluded: 'Excluded' };
223	
224	  // openSpanRef only lives in memory — leaving Annotate and coming back (or a
225	  // reload) resets it to {} even though an unclosed span from the previous
226	  // session is still sitting in the loaded data with end_frame=null. Reseed
227	  // it once that data arrives, or the next O/P press opens a second span
228	  // instead of closing the first.
229	  useEffect(() => {
230	    for (const kind of ['corner_swap', 'excluded'] as const) {
231	      if (openSpanRef.current[kind] != null) continue;
232	      const open = spans.find(s => s.kind === kind && s.end_frame == null);
233	      if (open) openSpanRef.current[kind] = open.id;
234	    }
235	  }, [spans]);
236	
237	  const toggleSpan = async (kind: SpanKind) => {
238	    if (!fightId) return;
239	    const openId = openSpanRef.current[kind];
240	    const frame = frameRef.current;
241	    if (openId != null) {
242	      try {
243	        const start = spans.find(s => s.id === openId)?.frame ?? frame;
244	        const patch = frame < start ? { frame, end_frame: start } : { end_frame: frame };
245	        const updated = await updateEvent(fightId, openId, patch);
246	        setAllEvents(prev => prev.map(s => (s.id === openId ? updated : s)));
247	        showToast(`${SPAN_LABEL[kind]} span closed`, 'var(--slate-400)', 'flag');
248	      } catch {
249	        showToast('Failed to close span', 'var(--f-red)', 'error');
250	      } finally {
251	        delete openSpanRef.current[kind];
252	      }
253	      return;
254	    }
255	    try {
256	      const created = await createEvent(fightId, {
257	        kind, frame, value: kind === 'excluded' ? 'replay' : null,
258	      });
259	      setAllEvents(prev => [...prev, created]);
260	      openSpanRef.current[kind] = created.id;
261	      showToast(`${SPAN_LABEL[kind]} span opened`, 'var(--slate-400)', 'flag');
262	    } catch {
263	      showToast('Failed to open span', 'var(--f-red)', 'error');
264	    }
265	  };
266	
267	  const updateSpan = async (spanId: number, patch: { frame?: number; end_frame?: number }) => {
268	    if (!fightId) return;
269	    try {
270	      const updated = await updateEvent(fightId, spanId, patch);
271	      setAllEvents(prev => prev.map(s => (s.id === spanId ? updated : s)));
272	    } catch {
273	      showToast('Failed to update span', 'var(--f-red)', 'error');
274	    }
275	  };
276	
277	  const removeSpan = async (spanId: number) => {
278	    if (!fightId) return;
279	    try {
280	      await deleteEvent(fightId, spanId);
281	      setAllEvents(prev => prev.filter(s => s.id !== spanId));
282	      for (const [kind, id] of Object.entries(openSpanRef.current)) {
283	        if (id === spanId) delete openSpanRef.current[kind as SpanKind];
284	      }
285	    } catch {
286	      showToast('Failed to delete span', 'var(--f-red)', 'error');
287	    }
288	  };
289	
290	  const undo = () => {
291	    const lastId = sessionIdsRef.current[sessionIdsRef.current.length - 1];
292	    if (lastId == null) return;
293	    removeEvent(lastId);
294	  };
295	
296	  const logTool = (item: ToolItem, shiftKey = false) => {
297	    if (!selectedFight) return;
298	    const corner = selRef.current;
299	    if (item.needsFighter && !corner) {
300	      setHint(true);
301	      clearTimeout(hintTimer.current);
302	      hintTimer.current = setTimeout(() => setHint(false), 1100);
303	      showToast('Select a fighter first', 'var(--f-red)', 'error');
304	      return;
305	    }
306	    // Fighter-independent tools (fight state) must not pick up whichever corner
307	    // happens to be selected — neither in the stored corner nor in the toast.
308	    const cornerIdx = item.needsFighter ? (corner === 'red' ? 0 : 1) : null;
309	    const fighterName = item.needsFighter ? (corner === 'red' ? redName : blueName) : '';
310	    const target = item.hasTarget ? (shiftKey ? 'body' : 'head') : item.fixedTarget ?? null;
311	    // `description` is only kept as a local for the toast text below — it's
312	    // no longer sent to the backend. Every action here except fight_end is
313	    // fully reconstructable from action/target/corner (see describeEvent.ts),
314	    // so storing a frozen copy would only go stale the next time a
315	    // corner_swap span is added or edited.
316	    const description = item.text(fighterName, target ?? undefined);
317	    const color = colorForAction(item.action);
318	    const icon = iconForAction(item.action);
319	    addEvent({
320	      frame: frameRef.current,
321	      corner: cornerIdx,
322	      action: item.action,
323	      target,
324	      success: successForAction(item.action),
325	    }).then(created => {
326	      if (!created) return;
327	      if (!item.needsFighter) { showToast(description, color, icon); return; }
328	      const targetSuffix = item.hasTarget ? ` · ${target === 'body' ? 'Body' : 'Head'}` : '';
329	      showToast(`${item.name} · ${fighterName}${targetSuffix}`, color, icon);
330	    });
331	  };
332	
333	  const confirmFightEnd = (result: FightEndResult) => {
334	    const winnerCorner = result.winner === 'red' ? 0 : result.winner === 'blue' ? 1 : null;
335	    const winnerName = result.winner === 'red' ? redName : result.winner === 'blue' ? blueName : null;
336	    const outcome = result.method === 'Draw' || !winnerName
337	      ? 'Draw'
338	      : result.method === 'Decision' ? `${winnerName} by decision` : `${winnerName} by ${result.method}`;
339	    const description = `Fight ended — ${outcome}${result.detail ? ' (' + result.detail + ')' : ''}`;
340	    const endFrame = frameRef.current;
341	    addEvent({
342	      frame: endFrame,
343	      description,
344	      corner: winnerCorner,
345	      action: 'fight_end',
346	      success: null,
347	    }).then(created => {
348	      if (!created) return;
349	      showToast(`Fight ended · ${result.method}`, 'var(--purple-600)', 'sports_score');
350	
351	      // The round span was seeded from the AI's scheduled-length guess,
352	      // which now runs past the real end of the fight — auto-exclude the
353	      // tail so it isn't scored/trained on as if it were live action.
354	      // Visible and editable in the timeline like any other excluded span,
355	      // not a silent adjustment (TODO.md #4).
356	      if (!fightId) return;
357	      const containingRound = spans.find(
358	        s => s.kind === 'round' && s.frame <= endFrame &&
359	             (s.end_frame == null || endFrame <= s.end_frame),
360	      );
361	      if (containingRound?.end_frame != null && containingRound.end_frame > endFrame) {
362	        createEvent(fightId, {
363	          kind: 'excluded',
364	          frame: endFrame + 1,
365	          end_frame: containingRound.end_frame,
366	          value: 'post fight_end',
367	        }).then(span => setAllEvents(prev => [...prev, span]));
368	      }
369	    });
370	    setEndOpen(false);
371	  };
372	
373	  const handleFinishLabeling = async () => {
374	    if (!fightId) return;
375	    setFinishing(true);
376	    try {
377	      await finishLabeling(fightId);
378	      // replace: Back from the Player must not land on this page again, which
379	      // for a now-finished fight is just the "already labeled" screen.
380	      navigate(`/fights/${fightId}`, { replace: true });
381	    } catch (err) {
382	      showToast(err instanceof Error ? err.message : 'Failed to finish labeling', 'var(--f-red)', 'error');
383	      setFinishing(false);
384	    }
385	  };
386	
387	  // Same transition the Player's "Edit labels" button makes, for a direct
388	  // visit to /annotate on a finished fight. Patching the one row in place
389	  // flips `ready`, so this page re-renders straight into the editor.
390	  const handleReopenLabeling = async () => {
391	    if (!fightId) return;
392	    setReopening(true);
393	    setReopenError(null);
394	    try {
395	      const reopened = await reopenLabeling(fightId);
396	      setFights(prev => prev.map(f => (f.id === reopened.id ? reopened : f)));
397	    } catch (err) {
398	      setReopenError(err instanceof Error ? err.message : 'Failed to open the fight for editing');
399	    } finally {
400	      setReopening(false);
401	    }
402	  };
403	
404	  const handleDeleteFight = async () => {
405	    if (!fightId) return;
406	    setDeletingFight(true);
407	    setDeleteError(null);
408	    try {
409	      // The DELETE unlinks the file this <video> is streaming — stop playback
410	      // (and the requestVideoFrameCallback loop) before pulling it out from under us.
411	      videoRef.current?.pause();
412	      setIsPlaying(false);
413	      await deleteFight(fightId);
414	      // replace: Back must not return to a now-dead /fights/{id}/annotate.
415	      navigate('/', { replace: true });
416	    } catch (err) {
417	      setDeleteError(err instanceof Error ? err.message : 'Failed to delete fight');
418	      setDeletingFight(false);
419	    }
420	  };
421	
422	  // stable "latest callback" ref so the global keydown listener (registered once)
423	  // always calls the current render's closures, without re-registering constantly
424	  const fnsRef = useRef({ togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent });
425	  fnsRef.current = { togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent };
426	
427	  useEffect(() => {
428	    if (!ready) return;
429	    const onKey = (e: KeyboardEvent) => {
430	      if (e.metaKey || e.ctrlKey || e.altKey) return;
431	      const target = e.target as HTMLElement;
432	      const tag = target.tagName;
433	      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return;
434	      // Any modal swallows every shortcut — otherwise z/o/p/digits keep logging
435	      // label events behind the overlay, and Escape would double-fire.
436	      if (endOpenRef.current || confirmDeleteRef.current) return;
437	
438	      const fns = fnsRef.current;
439	      const k = e.key;
440	      const time = (frameRef.current - 1) / fpsRef.current;
441	
442	      if (k === ' ') { e.preventDefault(); fns.togglePlay(); return; }
443	      if (k === 'ArrowLeft') { e.preventDefault(); handleSeek(Math.max(0, time - (e.shiftKey ? 5 : 1))); return; }
444	      if (k === 'ArrowRight') { e.preventDefault(); handleSeek(time + (e.shiftKey ? 5 : 1)); return; }
445	      if (k === ',') { e.preventDefault(); fns.stepFrame(-1); return; }
446	      if (k === '.') { e.preventDefault(); fns.stepFrame(1); return; }
447	      if (k === 'Escape') { fns.setSelected(null); setSelectedEventId(null); return; }
448	
449	      const lk = k.length === 1 ? k.toLowerCase() : k;
450	      if (lk === 'r') { fns.setSelected('red'); return; }
451	      if (lk === 'b') { fns.setSelected('blue'); return; }
452	      // Backspace/Delete: delete the selected timeline clip if one is
453	      // selected, else undo the last event logged this session. On Mac the
454	      // one physical "delete" key sends Backspace (e.key === 'Delete' is
455	      // only the separate forward-delete, Fn+Delete) — so this has to be
456	      // one binding that branches on selection, not two separate keys.
457	      if (k === 'Backspace' || k === 'Delete') {
458	        e.preventDefault();
459	        if (selectedEventIdRef.current != null) fns.removeEvent(selectedEventIdRef.current);
460	        else fns.undo();
461	        return;
462	      }
463	      if (lk === 'z') { e.preventDefault(); fns.undo(); return; }
464	      if (lk === 'o') { e.preventDefault(); fns.toggleSpan('corner_swap'); return; }
465	      if (lk === 'p') { e.preventDefault(); fns.toggleSpan('excluded'); return; }
466	
467	      // Digit keys need e.code, not e.key: Shift+1 types '!' on a US layout,
468	      // so reading e.key would break the KEYMAP lookup for the target modifier.
469	      const toolKey = e.code.startsWith('Digit') ? e.code.slice(5) : lk;
470	      const tool = KEYMAP[toolKey];
471	      if (tool) { e.preventDefault(); fns.logTool(tool, e.shiftKey); }
472	    };
473	    window.addEventListener('keydown', onKey);
474	    return () => window.removeEventListener('keydown', onKey);
475	  }, [ready]);
476	
477	  // ---- guard states ----
478	  if (selectedFight === null) {
479	    return (
480	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
481	        <span className="material-symbols-outlined" style={{ fontSize: 32, color: 'var(--text-muted)', animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
482	      </div>
483	    );
484	  }
485	
486	  if (isFightViewable(selectedFight.state)) {
487	    return (
488	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
489	        <div className="glass" style={{ textAlign: 'center', borderRadius: 12, padding: '48px 56px', maxWidth: 420 }}>
490	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: 'var(--text-primary)', display: 'block', marginBottom: 16 }}>check_circle</span>
491	          <h2 className="font-display" style={{ fontSize: 24, lineHeight: 1.05, margin: '0 0 10px', color: 'var(--text-primary)' }}>This fight is already labeled</h2>
492	          <p style={{ fontSize: 14, color: 'var(--text-muted)', margin: '0 0 20px', lineHeight: 1.6 }}>Open it in the Player to review the tagged events.</p>
493	          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
494	            <button onClick={() => navigate(`/fights/${selectedFight.id}`)} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 500, whiteSpace: 'nowrap' }}>
495	              <span className="material-symbols-outlined" style={{ fontSize: 16 }}>play_circle</span>
496	              Open Player
497	            </button>
498	            {isLabelEditable(selectedFight) && (
499	              <button onClick={handleReopenLabeling} disabled={reopening} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 500, whiteSpace: 'nowrap', cursor: reopening ? 'not-allowed' : 'pointer', opacity: reopening ? 0.6 : 1 }}>
500	                <span className="material-symbols-outlined" style={{ fontSize: 16 }}>{reopening ? 'progress_activity' : 'edit'}</span>
501	                Edit labels
502	              </button>
503	            )}
504	          </div>
505	          {reopenError && (
506	            <p style={{ fontSize: 12, fontWeight: 500, color: 'var(--red-500)', margin: '14px 0 0' }}>{reopenError}</p>
507	          )}
508	        </div>
509	      </div>
510	    );
511	  }
512	
513	  if (!ready) {
514	    return (
515	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
516	        <div className="glass" style={{ textAlign: 'center', borderRadius: 12, padding: '48px 56px', maxWidth: 420 }}>
517	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: 'var(--text-muted)', display: 'block', marginBottom: 16, animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
518	          <h2 className="font-display" style={{ fontSize: 24, lineHeight: 1.05, margin: '0 0 10px', color: 'var(--text-primary)' }}>
519	            {STATE_LABELS[selectedFight.state] ?? 'Detecting fighters'}
520	          </h2>
521	          <p style={{ fontSize: 14, color: 'var(--text-muted)', margin: '0 0 20px', lineHeight: 1.6 }}>
522	            Fighters are still being detected — labeling opens once that's done.
523	          </p>
524	          <button onClick={() => navigate('/')} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 500 }}>
525	            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>arrow_back</span>
526	            Back to fights
527	          </button>
528	        </div>
529	      </div>
530	    );
531	  }
532	
533	  return (
534	    <div style={{ position: 'relative', zIndex: 1, width: '100%', boxSizing: 'border-box', maxWidth: 1560, margin: '0 auto', padding: narrow ? '16px 14px 48px' : '22px 30px 70px' }}>
535	      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
536	        <button onClick={() => navigate('/')} className="icon-btn" style={{ width: 38, height: 38 }}>
537	          <span className="material-symbols-outlined" style={{ fontSize: 20 }}>arrow_back</span>
538	        </button>
539	        <div>
540	          <div className="font-display" style={{ fontSize: 30, color: 'var(--text-primary)', lineHeight: 1 }}>
541	            {isEditingLabels(selectedFight) ? 'Edit labels' : 'Self-annotate'}
542	          </div>
543	          <div style={{ fontSize: 12.5, color: 'var(--text-muted)', fontWeight: 500, marginTop: 3 }}>{redName} vs {blueName}</div>
544	        </div>
545	        <FightPurposeBadge purpose={selectedFight.purpose} />
546	        <span style={{ flex: 1 }} />
547	        <SaveStatus saving={savingCount > 0} />
548	        <button
549	          onClick={handleFinishLabeling}
550	          disabled={finishing}
551	          className="btn-primary"
552	          style={{
553	            display: 'inline-flex', alignItems: 'center', gap: 8,
554	            fontWeight: 600, fontSize: 13, padding: '9px 16px',
555	            cursor: finishing ? 'not-allowed' : 'pointer', opacity: finishing ? 0.5 : 1, fontFamily: 'inherit',
556	          }}
557	        >
558	          <span className="material-symbols-outlined" style={{ fontSize: 18 }}>{finishing ? 'progress_activity' : 'task_alt'}</span>
559	          Finish labeling
560	        </button>
561	        {can('admin') && (
562	          <button
563	            onClick={() => { setDeleteError(null); setConfirmDelete(true); }}
564	            title="Delete this fight"
565	            style={{
566	              width: 38, height: 38, flexShrink: 0, display: 'grid', placeItems: 'center',
567	              borderRadius: 6, border: '1px solid var(--f-red-dim)',
568	              background: 'rgba(239,68,68,0.08)', color: 'var(--red-500)',
569	              cursor: 'pointer', fontFamily: 'inherit',
570	            }}
571	          >
572	            <span className="material-symbols-outlined" style={{ fontSize: 20 }}>delete</span>
573	          </button>
574	        )}
575	      </div>
576	
577	      <ConfirmDialog
578	        open={confirmDelete}
579	        title="Delete fight?"
580	        message={
581	          <>
582	            <strong style={{ color: 'var(--text-primary)' }}>{redName} vs {blueName}</strong> will be
583	            permanently deleted — the source video file, every hand label and span you have annotated
584	            so far, plus all pipeline predictions, rounds and tracked fighter frames. This cannot be undone.
585	          </>
586	        }
587	        confirmLabel="Delete fight"
588	        confirmIcon="delete_forever"
589	        danger
590	        busy={deletingFight}
591	        error={deleteError}
592	        onCancel={() => setConfirmDelete(false)}
593	        onConfirm={handleDeleteFight}
594	      />
595	
596	      {needsRoundReview(selectedFight) && (
597	        <div style={{
598	          display: 'flex',
599	          alignItems: 'flex-start',
600	          gap: 10,
601	          marginBottom: 14,
602	          padding: '11px 14px',
603	          borderRadius: 6,
604	          border: '1px solid color-mix(in srgb, var(--warn) 25%, transparent)',
605	          background: 'color-mix(in srgb, var(--warn) 7%, transparent)',
606	        }}>
607	          <span className="material-symbols-outlined" style={{ fontSize: 19, color: 'var(--warn)', flexShrink: 0 }}>
608	            rule
609	          </span>
610	          <div style={{ minWidth: 0 }}>
611	            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--warn)', marginBottom: 2 }}>
612	              Round boundaries are unverified
613	            </div>
614	            <div style={{ fontSize: 12.5, color: 'var(--text-secondary)', lineHeight: 1.5 }}>
615	              {selectedFight.segmentation_review_reason
616	                ?? 'Segmentation could not confirm these rounds against the scoreboard.'}
617	              {' '}Check the Rounds lane below and drag the edges before labelling.
618	            </div>
619	          </div>
620	        </div>
621	      )}
622	
623	      <div style={{ display: 'grid', gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'minmax(0, 1fr) 460px', gap: 16, alignItems: 'stretch' }}>
624	        <div style={{ display: 'flex', flexDirection: 'column' }}>
625	          <AnnotateStage
626	            videoRef={videoRef}
627	            overlayRef={overlayRef}
628	            src={videoSrc}
629	            isPlaying={isPlaying}
630	            onTimeUpdate={() => { const v = videoRef.current; if (v) setCurrentTime(v.currentTime); }}
631	            onLoadedMetadata={() => { const v = videoRef.current; if (v) setDuration(v.duration); }}
632	            onPlay={() => setIsPlaying(true)}
633	            onPause={() => setIsPlaying(false)}
634	            onTogglePlay={togglePlay}
635	            onStepForward={() => stepFrame(1)}
636	            onStepBackward={() => stepFrame(-1)}
637	            frameMap={frameMap}
638	            fightWidth={selectedFight.width}
639	            fightHeight={selectedFight.height}
640	            currentRound={currentRound}
641	            selectedCorner={selected}
642	            redName={redName}
643	            blueName={blueName}
644	            toast={toast}
645	          />
646	
647	          <VideoControls
648	            isPlaying={isPlaying}
649	            currentTime={currentTime}
650	            duration={duration}
651	            onTogglePlay={togglePlay}
652	            onSeek={handleSeek}
653	            onStepBackward={() => stepFrame(-1)}
654	            onStepForward={() => stepFrame(1)}
655	          />
656	
657	          <FrameInfo currentFrame={currentFrame} currentMs={currentMs} fps={fps} />
658	
