663	          <div className="glass" style={{ padding: '18px 18px 20px', borderRadius: 12 }}>
664	            <div className="label" style={{ marginBottom: 11 }}>Active fighter</div>
665	            <FighterSelectCard
666	              selected={selected}
667	              onSelect={c => setSelected(s => (s === c ? null : c))}
