76	interface AnnotationTimelineProps {
77	  events: Event[];
78	  spans: Event[];
79	  rounds: Round[];
80	  duration: number;
81	  fps: number;
82	  currentFrame: number;
83	  onSeek: (frame: number) => void;
84	  onSetPlaying: (playing: boolean) => void;
85	  onUpdateSpan: (id: number, patch: { frame?: number; end_frame?: number }) => void;
86	  onDeleteSpan: (id: number) => void;
87	  flashId: number | null;
88	  selectedEventId: number | null;
89	  onSelectEvent: (id: number | null) => void;
90	  filter: string;
91	  redName: string;
92	  blueName: string;
93	  describe: (e: Event) => string;
94	}
95	
96	export default function AnnotationTimeline({
97	  events, spans, rounds, duration, fps, currentFrame, onSeek, onSetPlaying, onUpdateSpan, onDeleteSpan,
98	  flashId, selectedEventId, onSelectEvent, filter, redName, blueName, describe,
99	}: AnnotationTimelineProps) {
100	  const [zoom, setZoom] = useState(1);
101	  const [hover, setHover] = useState<Hover | null>(null);
102	  const [scrollRef, scrollW] = useMeasure();
103	  const draggingRef = useRef(false);
104	
105	  const time = (currentFrame - 1) / fps;
106	  const frameFor = (t: number) => Math.max(1, Math.round(t * fps) + 1);
107	  const xFor = (frame: number) => ((frame - 1) / fps) * pxPerSec;
108	
109	  const fitPx = scrollW > 0 ? scrollW / Math.max(duration, 1) : 2.2;
110	  const pxPerSec = fitPx * zoom;
111	  const W = duration * pxPerSec;
112	  const spansTop = TL.ruler + TL.round + TL.state;
113	  const lanesTop = spansTop + TL.span * 2;
114	  const totalH = lanesTop + TL.lane * 2;
115	  const boxH = totalH + 14;
116	
117	  // Live edge being dragged, so the block redraws smoothly before the PUT commits.
118	  const dragRef = useRef<{ id: number; edge: 'start' | 'end' } | null>(null);
119	  const [dragFrame, setDragFrame] = useState<number | null>(null);
120	
121	  const fil = (e: Event) => matchFilter(categoryForAction(e.action), filter);
122	  const redEv = events.filter(e => laneFor(e) === 'red' && e.action !== 'fight_end' && fil(e));
123	  const blueEv = events.filter(e => laneFor(e) === 'blue' && e.action !== 'fight_end' && fil(e));
124	  const roundEv = events.filter(e => categoryForAction(e.action) === 'round' || e.action === 'fight_end');
125	  // Everything after fight_end is dead air (celebration, doctor check, corner
126	  // talk) — the round span and the last state segment are visually capped
127	  // here to end there, so the timeline actually looks like the fight is
128	  // over. The underlying round span's real end_frame is untouched (only the
129	  // auto-created `excluded` span makes the tail harmless for scoring/export
130	  // — see Annotate.tsx's confirmFightEnd); this is display-only.
131	  const fightEndFrame = events.find(e => e.action === 'fight_end')?.frame ?? null;
132	  const stateEv = useMemo(
133	    () => events.filter(e => categoryForAction(e.action) === 'state').sort((a, b) => a.frame - b.frame),
134	    [events],
135	  );
136	  const segs = stateEv
137	    .map((e, i) => {
138	      const rawT1 = i + 1 < stateEv.length ? (stateEv[i + 1].frame - 1) / fps : duration;
139	      const t1 = fightEndFrame != null ? Math.min(rawT1, (fightEndFrame - 1) / fps) : rawT1;
140	      return {
141	        id: e.id,
142	        t0: (e.frame - 1) / fps,
143	        t1,
144	        state: e.action === 'state_clinch' ? 'CLINCH' : e.action === 'state_ground' ? 'GROUND' : 'STRIKING',
145	      };
146	    })
147	    .filter(s => s.t1 >= s.t0); // drop a segment that starts entirely after fight_end
148	
149	  // Same display-only capping as the state segments above: the round block
150	  // that contains fight_end is drawn ending there instead of at its real
151	  // (now-stale) end_frame. Edge-drag still targets the real span by id, so
152	  // dragging the end handle still writes the true end_frame — it just
153	  // starts from the visually-capped position rather than the stale one.
154	  const roundSpans = spans
155	    .filter(s => s.kind === 'round')
156	    .map(s => (
157	      fightEndFrame != null && s.end_frame != null &&
158	      s.frame <= fightEndFrame && fightEndFrame < s.end_frame
159	        ? { ...s, end_frame: fightEndFrame }
160	        : s
161	    ));
162	  const cornerSwapSpans = spans.filter(s => s.kind === 'corner_swap');
163	  const excludedSpans = spans.filter(s => s.kind === 'excluded');
164	
165	  const targets = [5, 10, 15, 30, 60, 120, 180];
166	  const tickEvery = targets.find(s => s * pxPerSec >= 64) || 240;
167	  const ticks: number[] = [];
168	  for (let t = 0; t <= duration; t += tickEvery) ticks.push(t);
169	
170	  const scrubRef = useRef<(clientX: number) => void>(() => {});
171	  scrubRef.current = (clientX: number) => {
172	    const el = scrollRef.current;
173	    if (!el) return;
174	    const r = el.getBoundingClientRect();
175	    const t = (clientX - r.left + el.scrollLeft) / pxPerSec;
176	    onSeek(frameFor(Math.max(0, Math.min(duration, t))));
177	  };
178	  useEffect(() => {
179	    const move = (e: PointerEvent) => { if (draggingRef.current) scrubRef.current(e.clientX); };
180	    const up = () => { draggingRef.current = false; };
181	    window.addEventListener('pointermove', move);
182	    window.addEventListener('pointerup', up);
183	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
184	  }, []);
185	  const startScrub = (e: React.PointerEvent) => {
186	    draggingRef.current = true;
187	    onSetPlaying(false);
188	    onSelectEvent(null); // clicking the background/ruler deselects whatever clip was selected
189	    scrubRef.current(e.clientX);
190	  };
191	
192	  // Edge-drag for span blocks (round / corner_swap / excluded resize handles).
193	  useEffect(() => {
194	    const move = (e: PointerEvent) => {
195	      const d = dragRef.current;
196	      const el = scrollRef.current;
197	      if (!d || !el) return;
198	      const r = el.getBoundingClientRect();
199	      const t = (e.clientX - r.left + el.scrollLeft) / pxPerSec;
200	      setDragFrame(frameFor(Math.max(0, Math.min(duration, t))));
201	    };
202	    const up = () => {
203	      const d = dragRef.current;
204	      if (d && dragFrame != null) {
205	        onUpdateSpan(d.id, d.edge === 'start' ? { frame: dragFrame } : { end_frame: dragFrame });
206	      }
207	      dragRef.current = null;
208	      setDragFrame(null);
209	    };
210	    window.addEventListener('pointermove', move);
211	    window.addEventListener('pointerup', up);
212	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
213	    // eslint-disable-next-line react-hooks/exhaustive-deps
214	  }, [pxPerSec, duration, dragFrame]);
215	  const startEdgeDrag = (id: number, edge: 'start' | 'end') => (e: React.PointerEvent) => {
216	    e.stopPropagation();
217	    onSetPlaying(false);
218	    dragRef.current = { id, edge };
219	  };
220	
221	  useEffect(() => {
222	    const el = scrollRef.current;
223	    if (!el) return;
224	    const x = xFor(currentFrame);
225	    const L = el.scrollLeft;
226	    const R = L + el.clientWidth;
227	    if (x < L + 48 || x > R - 48) el.scrollLeft = x - el.clientWidth / 2;
228	    // eslint-disable-next-line react-hooks/exhaustive-deps
229	  }, [time, pxPerSec]);
230	
231	  const TrackHead = ({ h, children, top }: { h: number; children: React.ReactNode; top: number }) => (
232	    <div style={{
233	      position: 'absolute', top, left: 0, height: h, width: TL.head, display: 'flex', alignItems: 'center', gap: 8,
234	      padding: '0 12px', boxSizing: 'border-box', borderBottom: '1px solid var(--border-subtle)',
235	      borderRight: '1px solid var(--border-glass)', background: 'var(--surface-inner)',
236	    }}>{children}</div>
237	  );
238	
239	  const playX = xFor(currentFrame);
240	
241	  // A span block with draggable edges (round/corner_swap) or a plain block
242	  // with a delete button (corner_swap/excluded). `end_frame == null` means
243	  // the start/end toggle is still open — draw it running to the playhead.
244	  const SpanBlock = ({ s, top, h, deletable }: { s: Event; top: number; h: number; deletable: boolean }) => {
245	    const dragging = dragRef.current?.id === s.id;
246	    const start = dragging && dragRef.current?.edge === 'start' && dragFrame != null ? dragFrame : s.frame;
247	    const end = dragging && dragRef.current?.edge === 'end' && dragFrame != null
248	      ? dragFrame
