253	    // SpanBlock only ever receives round/corner_swap/excluded rows (see the
254	    // `spans` prop, always pre-filtered to kind !== 'point' by the caller).
255	    const c = SPAN_COLOR[s.kind as SpanKind];
256	    return (
257	      <div
258	        style={{
259	          position: 'absolute', top, left: x0, width: w, height: h, borderRadius: 5, zIndex: 3,
260	          background: `color-mix(in srgb, ${c} ${open ? 10 : 16}%, transparent)`,
261	          border: `1px solid color-mix(in srgb, ${c} ${open ? 55 : 38}%, transparent)`,
262	          borderStyle: open ? 'dashed' : 'solid',
