298	            title="Delete"
299	            style={{
300	              position: 'absolute', right: 2, top: '50%', transform: 'translateY(-50%)', width: 14, height: 14,
301	              borderRadius: 4, border: 'none', background: 'rgba(0,0,0,0.35)', color: c, cursor: 'pointer',
302	              display: 'grid', placeItems: 'center', padding: 0, zIndex: 5,
303	            }}
