309	    );
310	  };
311	
312	  return (
313	    <div style={{ display: 'flex', position: 'relative', height: boxH, borderRadius: 8, overflow: 'hidden', border: '1px solid var(--border-glass)' }}>
314	      <div style={{ position: 'relative', width: TL.head, flexShrink: 0, background: 'var(--surface-inner)', zIndex: 8 }}>
