window.__writes = [];
const realFetch = window.fetch.bind(window);
let nextId = 900000;
const store = {};
window.fetch = async (input, init = {}) => {
  const url = typeof input === 'string' ? input : input.url;
  const method = (init.method || 'GET').toUpperCase();
  const json = (b, s=200) => new Response(JSON.stringify(b), { status: s, headers: { 'Content-Type': 'application/json' } });
  if (method === 'GET' && /\/api\/fights\/?$/.test(url)) {
    const fights = await realFetch(input, init).then(r => r.json());
    return json(fights.map(f => f.id === 58 ? { ...f, state: 'labeling_in_progress', labeled_at: null } : f));
  }
  const m = url.match(/\/api\/fights\/58\/events\/(\d+)?/);
  if (m && method === 'GET') {
    const ev = await realFetch(input, init).then(r => r.json());
    ev.forEach(e => { store[e.id] = e; });
    return json(Object.values(store).filter(e => e.source === 'label').sort((a,b)=>a.frame-b.frame));
  }
  if (method !== 'GET') {
    window.__writes.push([method, url, init.body]);
